const gpu = new GPU({ mode });

const grayscale = gpu.createKernel(function (image) {
  const pixel = image[this.thread.y][this.thread.x];
  const l = 0.299 * pixel[0]
          + 0.587 * pixel[1]
          + 0.114 * pixel[2];
  this.color(l, l, l, 1);
}, {
  output: [512, 512],
  graphical: true,
});

grayscale(inputImage);
render(grayscale.canvas);
