const gpu = new GPU({ mode });

const sumAll = gpu.createKernel(function (data) {
  let sum = 0;
  for (let i = 0; i < this.constants.n; i++) {
    sum += data[i];
  }
  return sum;
}, {
  output: [1],
  constants: { n: 4096 },
});

